package com.farm2market.controller;
import com.farm2market.dto.*; import com.farm2market.entity.*; import com.farm2market.repository.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {final OrderRepository orders;final ProductRepository products;final UserRepository users;OrderController(OrderRepository o,ProductRepository p,UserRepository u){orders=o;products=p;users=u;} @GetMapping("/my") public List<Order> my(@RequestParam String buyerEmail){return orders.findByBuyerOrderByCreatedAtDesc(users.findByEmail(buyerEmail).orElseThrow());} @PostMapping public Order create(@Valid @RequestBody OrderRequest x,@RequestParam String buyerEmail){User b=users.findByEmail(buyerEmail).orElseThrow();Order o=new Order();o.setBuyer(b);o.setDeliveryLocation(x.deliveryLocation());double total=0;for(OrderLine l:x.items()){Product p=products.findById(l.productId()).orElseThrow();if(p.getAvailableQuantity()<l.quantity())throw new RuntimeException("Insufficient quantity for "+p.getName());p.setAvailableQuantity(p.getAvailableQuantity()-l.quantity());products.save(p);OrderItem i=new OrderItem();i.setOrder(o);i.setProduct(p);i.setQuantity(l.quantity());i.setPrice(p.getPricePerKg());i.setSubtotal(l.quantity()*p.getPricePerKg());o.getItems().add(i);total+=i.getSubtotal();o.setFarmer(p.getFarmer());}o.setTotalAmount(total);return orders.save(o);} @PutMapping("/{id}/status") public Order status(@PathVariable Long id,@Valid @RequestBody StatusRequest x){Order o=orders.findById(id).orElseThrow();o.setStatus(x.status());return orders.save(o);}}
